# Find all rectangles with 2 as boundaries
def find_rectangles(grid):
    h, w = len(grid), len(grid[0])
    rectangles = []

    for r1 in range(h):
        for c1 in range(w):
            if grid[r1][c1] == 2:
                # Try to find a rectangle starting at (r1, c1)
                for rect_size in range(1, min(h-r1, w-c1)+1):
                    r2 = r1 + rect_size - 1
                    c2 = c1 + rect_size - 1
                    if c2 >= w or r2 >= h:
                        continue

                    # Check if this is a valid rectangle (all boundaries are 2)
                    is_rectangle = True
                    for ir in range(r1, r2+1):
                        if not is_rectangle:
                            break
                        # Check horizontal boundaries
                        if ir == r1 or ir == r2:
                            for ic in range(c1, c2+1):
                                if grid[ir][ic] != 2:
                                    is_rectangle = False
                                    break
                        else:
                            # Check vertical boundaries only at c1 and c2
                            if grid[ir][c1] != 2 or grid[ir][c2] != 2:
                                is_rectangle = False
                                break

                    if is_rectangle:
                        # Check if interior is empty (0)
                        interior = True
                        for ir in range(r1+1, r2):
                            if not interior:
                                break
                            if not (grid[ir][c1] == 0 and grid[ir][c2] == 0):
                                # Check if there's a complex interior
                                for ic in range(c1, c2+1):
                                    if grid[ir][ic] != 0:
                                        interior = False
                                        break
                                if not interior:
                                    break

                        # If it's a valid hollow rectangle with empty interior
                        if is_rectangle and interior and rect_size > 1:
                            rect = (r1, c1, r2, c2)  # top-left, bottom-right
                            rectangles.append(rect)
                            # Move past this rectangle
                            r1 = r2
                            break

    return rectangles

