# Find rectangles (bounding boxes)
def find_bounding_boxes(points):
    if not points:
        return []

    # For each point, try to find a rectangular bounding box that contains only 2s on boundary
    boxes = []
    for (r1, c1) in points:
        # Find max row and col that form a box with this corner
        for r2 in range(r1, h):
            for c2 in range(c1, w):
                # Check if (r1,c1)-(r2,c2) is a valid rectangular boundary
                if not is_valid_rectangle_box(points, r1, c1, r2, c2):
                    continue

                # Size
                height = r2 - r1 + 1
                width = c2 - c1 + 1

                boxes.append((r1, c1, r2, c2, height, width))

                # Avoid duplicates by limiting search
                if c2 > c1:
                    break

    # Deduplicate
    unique = []
    seen = set()
    for box in boxes:
        key = (box[0], box[1], box[2], box[3])
        if key not in seen:
            seen.add(key)
            unique.append(box)

    return unique

def is_valid_rectangle_box(points, r1, c1, r2, c2):
    h = r2 - r1 + 1
    w = c2 - c1 + 1

    # Check all boundary points are in points
    for r in range(r1, r2+1):
        for c in range(c1, c2+1):
            if r == r1 or r == r2 or c == c1 or c == c2:
                if (r, c) not in points:
                    return False
    return True

